import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const file='deliverables/라이나생명_관련사이트_보안점검_통합보완보고서_20261101.html';
const html=fs.readFileSync(file,'utf8');
const script=html.match(/<script>([\s\S]*?)<\/script>/)?.[1];assert(script);
const elements=new Map();
const element=()=>({value:'',textContent:'',hidden:false,handlers:{},addEventListener(name,fn){this.handlers[name]=fn;}});
for(const name of ['search','priority','reset','count','expand','print'])elements.set(name,element());
const rows=[...html.matchAll(/<tr data-asset data-priority="([^"]*)" data-state="([^"]*)">([\s\S]*?)<\/tr>/g)].map(m=>({...element(),dataset:{priority:m[1],state:m[2]},textContent:m[3].replace(/<[^>]+>/g,' ')}));assert.equal(rows.length,27);
const details=Array.from({length:45},()=>({open:false}));
const trials=details.slice(0,44),events={},classes=new Set();
let prints=0;
const context=vm.createContext({document:{body:{classList:{add:x=>classes.add(x),remove:x=>classes.delete(x)}},querySelectorAll:q=>q==='[data-asset]'?rows:q==='[data-trial]'?trials:details,getElementById:id=>elements.get(id)},window:{addEventListener:(n,f)=>events[n]=f,print:()=>prints++}});
vm.runInContext(script,context,{timeout:1000});
elements.get('search').value='ga.lina.co.kr';elements.get('search').handlers.input();assert(rows.some(r=>r.hidden)&&rows.some(r=>!r.hidden));
elements.get('search').value='UNMATCHED_LOCAL_MARKER';elements.get('search').handlers.input();assert(rows.every(r=>r.hidden));
elements.get('reset').handlers.click();assert(rows.every(r=>!r.hidden));
elements.get('priority').value='높음';elements.get('priority').handlers.change();assert(rows.filter(r=>!r.hidden).every(r=>r.dataset.priority==='높음'));
elements.get('expand').handlers.click();assert(trials.every(x=>x.open));elements.get('expand').handlers.click();assert(trials.every(x=>!x.open));
events.beforeprint();assert(classes.has('print-all'));assert(details.every(x=>x.open));events.afterprint();assert(!classes.has('print-all'));assert(details.every(x=>!x.open));
elements.get('print').handlers.click();assert.equal(prints,1);
const missing=[];
for(const [,href] of html.matchAll(/href="([^"]+)"/g)){if(/^(?:https?:|#)/.test(href))continue;const target=path.resolve(path.dirname(file),decodeURIComponent(href.replaceAll('&amp;','&')));if(!fs.existsSync(target))missing.push(target);}
assert.equal(missing.length,0);
const data={file,checkedAt:new Date().toISOString(),scope:'Static HTML and script behavior with a mock DOM; no browser layout or actual print pagination verification',checks:{scriptSyntax:true,search:true,emptySearchResult:true,reset:true,priorityFilter:true,expand44Trials:true,printAllAndRestore:true,localLinks:true},missingLocalLinks:missing,visualInspection:'NOT_RUN'};
fs.writeFileSync('report_qa/consolidated-1793512164954/interaction-verification.json',JSON.stringify(data,null,2),{flag:'wx'});
console.log(JSON.stringify(data));
